// Generated by SymplrV3 — switches the active environment.
// Usage: node scripts/use-env.mjs <name>   (or: npm run env:<name>)
// Copies .env.<name> → .env, then merges .env.secrets (gitignored) over it —
// secure values never live in the committed .env.<name> files.
import { existsSync, readFileSync, readdirSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

const root = join(import.meta.dirname, '..');
const name = process.argv[2];
const available = readdirSync(root)
  .filter((f) => f.startsWith('.env.') && !f.endsWith('.example') && f !== '.env.secrets')
  .map((f) => f.slice('.env.'.length));
if (!name || !existsSync(join(root, '.env.' + name))) {
  console.error('Usage: npm run env:<name>  — available: ' + available.join(', '));
  process.exit(1);
}
let env = readFileSync(join(root, '.env.' + name), 'utf8');

const secretsPath = join(root, '.env.secrets');
let filled = 0;
let missing = 0;
if (existsSync(secretsPath)) {
  const secrets = {};
  for (const line of readFileSync(secretsPath, 'utf8').split('\n')) {
    const m = /^([A-Za-z_]\w*)=(.*)$/.exec(line.trim());
    if (m && m[2] !== '') secrets[m[1]] = m[2];
  }
  env = env
    .split('\n')
    .map((line) => {
      const m = /^([A-Za-z_]\w*)=/.exec(line);
      if (m && secrets[m[1]] !== undefined) { filled++; return m[1] + '=' + secrets[m[1]]; }
      return line;
    })
    .join('\n');
}
// secure placeholders still empty after the merge
missing = env.split('\n').filter((l) => /^EXPO_PUBLIC_\w*=$/.test(l)).length;

writeFileSync(join(root, '.env'), env);
let note = 'Switched to "' + name + '"';
if (filled) note += ' (' + filled + ' secure value' + (filled === 1 ? '' : 's') + ' merged from .env.secrets)';
if (missing) note += ' — ⚠ ' + missing + ' var(s) still empty; fill .env.secrets (see .env.secrets.example)';
console.log(note + '. Restart the bundler (with cache reset) to pick it up.');
